A1 = [0	-0.4000; %[output:group:3a453f84] %[output:87fed15c]
    0.2500	0] %[output:group:3a453f84] %[output:87fed15c]
A2 = [0	0.1667; %[output:group:65e2a07e] %[output:1a85e0c8]
    0.2500	0] %[output:group:65e2a07e] %[output:1a85e0c8]
A3 = [0	0.1667; %[output:group:4472171d] %[output:6ffeab68]
    -0.4000	0] %[output:group:4472171d] %[output:6ffeab68]

x_0 = [10e-4; 0];
t_vec = 0:0.01:30;

x1_t = cell2mat(arrayfun(@(t) expm(A1*t)*x_0, ...
        t_vec, 'UniformOutput', false));
x2_t = cell2mat(arrayfun(@(t) expm(A2*t)*x_0, ...
    t_vec, 'UniformOutput', false));
x3_t = cell2mat(arrayfun(@(t) expm(A3*t)*x_0, ...
    t_vec, 'UniformOutput', false));

f = figure; %[output:06c26275]

tl = tiledlayout(f, 3, 1) %[output:4f42b95f] %[output:06c26275]
ax = nexttile(tl); %[output:06c26275]
hold(ax, 'on'); %[output:06c26275]
plot(ax, t_vec, x1_t(1, :), 'LineWidth', 1.5); %[output:06c26275]
plot(ax, t_vec, x1_t(2, :), 'LineWidth', 1.5); %[output:06c26275]

ylabel('b1 spin') %[output:06c26275]
xlabel('time (s)'); %[output:06c26275]
legend('\Delta\omega_2', '\Delta\omega_3') %[output:06c26275]
legend('Location','eastoutside'); %[output:06c26275]
ax = nexttile(tl); %[output:06c26275]
hold(ax, 'on'); %[output:06c26275]
plot(ax, t_vec, x2_t(1, :), 'LineWidth', 1.5); %[output:06c26275]
plot(ax, t_vec, x2_t(2, :), 'LineWidth', 1.5); %[output:06c26275]
ylabel(ax, 'b2 spin'); %[output:06c26275]
xlabel(ax, 'time (s)'); %[output:06c26275]
legend(ax, '\Delta\omega_1', '\Delta\omega_3'); %[output:06c26275]
legend('Location','eastoutside'); %[output:06c26275]
ax = nexttile(tl); %[output:06c26275]
hold(ax, 'on'); %[output:06c26275]
plot(ax, t_vec, x3_t(1, :), 'LineWidth', 1.5); %[output:06c26275]
plot(ax, t_vec, x3_t(2, :), 'LineWidth', 1.5); %[output:06c26275]
ylabel(ax, 'b3 spin'); %[output:06c26275]
xlabel(ax, 'time (s)'); %[output:06c26275]
legend(ax, '\Delta\omega_1', '\Delta\omega_2'); %[output:06c26275]
legend('Location','eastoutside'); %[output:06c26275]

